    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });

  const result = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 2 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].qty, 7); // 5 + 2
  assert.equal(result.value.lines[1].qty, 3); // unchanged
});

