  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 15);
});

test('createInvoice: discountPercent of 0 overrides tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier (5%)
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 0 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 0);
});

test('createInvoice: multiple lines get tier discount', () => {
  const result = createInvoice({
    customerId: 'C-003', // Silver tier (2.5%)
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'COPY-HOUR', qty: 2 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 2.5);
  assert.equal(result.value.lines[1].discountPercent, 2.5);
  assert.equal(result.value.lines[2].discountPercent, 2.5);
});

test('createInvoice: tier discount mixed with explicit discounts', () => {
  const result = createInvoice({
    customerId: 'C-003', // Silver tier (2.5%)
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 }, // Gets 2.5% tier discount
      { sku: 'DES-HOUR', qty: 3, discountPercent: 10 }, // Override with 10%
      { sku: 'COPY-HOUR', qty: 2 }, // Gets 2.5% tier discount
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].discountPercent, 2.5);
  assert.equal(result.value.lines[1].discountPercent, 10);
  assert.equal(result.value.lines[2].discountPercent, 2.5);
});

test('invoiceTotals: with tier discount', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier (5%)
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);

  // Subtotal: 95000, Discount: 4750 (5%), After: 90250, VAT: 18952.5 → 18952 (banker's rounding)
  assert.equal(totals.ok, true);
  assert.equal(totals.value.subtotal, 95000);
  assert.equal(totals.value.discount, 4750);
  assert.equal(totals.value.vat, 18952);
  assert.equal(totals.value.total, 109202);
});

test('addLine: new line gets tier discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001', // Gold tier (5%)
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 5); // Gold tier discount
});

test('addLine: explicit discount overrides tier discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001', // Gold tier (5%)
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3, discountPercent: 10 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[1].discountPercent, 10);
});

test('addLine: updating existing line does not apply tier discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001', // Gold tier (5%)
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }], // Has 5% discount
  });

  const result = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 5 });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].qty, 10);
  assert.equal(result.value.lines[0].discountPercent, 5); // Keeps original discount
});

test('different tiers apply different discounts', () => {
  const gold = createInvoice({
    customerId: 'C-001', // Gold
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });

  const silver = createInvoice({
    customerId: 'C-003', // Silver
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });

  const standard = createInvoice({
    customerId: 'C-002', // Standard
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });

  const goldTotals = invoiceTotals(gold.value);
  const silverTotals = invoiceTotals(silver.value);
  const standardTotals = invoiceTotals(standard.value);

  assert.equal(goldTotals.value.discount, 47500); // 5% of 950000
  assert.equal(silverTotals.value.discount, 23750); // 2.5% of 950000
  assert.equal(standardTotals.value.discount, 0); // No discount
});

