test('lineDiscount: 10% discount', () => {
  const line = {
    qty: 10,
    unitPrice: 9500,
    discountPercent: 10,
  };

  const result = lineDiscount(line);

  assert.equal(result.ok, true);
  assert.equal(result.value, 9500); // 10% of 95000 = 9500
});

test('lineDiscount: 50% discount', () => {
  const line = {
    qty: 100,
    unitPrice: 1000,
    discountPercent: 50,
  };

  const result = lineDiscount(line);

  assert.equal(result.ok, true);
  assert.equal(result.value, 50000); // 50% of 100000 = 50000
});

test('lineDiscount: fractional discount with rounding', () => {
  const line = {
    qty: 3,
    unitPrice: 1000, // 3000 total
    discountPercent: 33.33,
  };

  const result = lineDiscount(line);

  assert.equal(result.ok, true);
  // 33.33% of 3000 = 999.9, rounds to 1000
  assert.equal(result.value, 1000);
});

test('lineDiscount: clamped at zero', () => {
  const line = {
    qty: 1,
    unitPrice: 0,
    discountPercent: 50,
  };

  const result = lineDiscount(line);

  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

