test('invoiceTotals: with single line discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  const totals = invoiceTotals(result.value);

  // Subtotal: 95000, Discount: 9500 (10%), After-discount: 85500, VAT: 17955 (21%)
  assert.equal(totals.ok, true);
  assert.equal(totals.value.subtotal, 95000);
  assert.equal(totals.value.discount, 9500);
  assert.equal(totals.value.vat, 17955);
  assert.equal(totals.value.total, 103455);
});

test('invoiceTotals: with multiple lines and mixed discounts', () => {
  const result = createInvoice({
    customerId: 'C-001', // Gold tier (5%)
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }, // 95000, discount 9500, after 85500, VAT 17955
      { sku: 'DES-HOUR', qty: 5 }, // 42500, tier discount 2125, after 40375, VAT 8479
      { sku: 'COPY-HOUR', qty: 3, discountPercent: 20 }, // 18000, discount 3600, after 14400, VAT 3024
    ],
  });

  const totals = invoiceTotals(result.value);

  assert.equal(totals.ok, true);
  assert.equal(totals.value.subtotal, 155500); // 95000 + 42500 + 18000
  assert.equal(totals.value.discount, 15225); // 9500 + 2125 + 3600
  assert.equal(totals.value.vat, 29458); // 17955 + 8479 + 3024
  assert.equal(totals.value.total, 169733); // 155500 - 15225 + 29458
});

test('invoiceTotals: discount cannot make total negative', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-10-15',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 1,
        unitPrice: 1000, // 1000 total
        vatRate: 21,
        discountPercent: 150, // 150% discount (invalid but shouldn't break clamping)
      },
    ],
  };

  const totals = invoiceTotals(invoice);

  // Even though discount is invalid, total should be clamped at 0
  assert.equal(totals.ok, false); // Should fail on DISCOUNT_INVALID
});

test('invoiceTotals: total is clamped at 0', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2024-10-15',
    status: 'draft',
    lines: [
      {
        sku: 'DEV-HOUR',
