        qty: 1,
        unitPrice: 1000,
        vatRate: 21,
        discountPercent: 100, // 100% discount
      },
    ],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.ok, true);
  assert.equal(totals.value.subtotal, 1000);
  assert.equal(totals.value.discount, 1000);
