});

test('invoiceTotals: with mixed VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-002', // Standard tier
    issueDate: '2024-10-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 }, // 95000, 21% VAT = 19950
      { sku: 'PRINT-A4', qty: 100 }, // 3700, 9% VAT = 333
      { sku: 'WORKSHOP-DAY', qty: 1 }, // 60000, 0% VAT = 0
    ],
  });

  const totals = invoiceTotals(result.value);

  assert.equal(totals.ok, true);
  assert.equal(totals.value.subtotal, 158700); // 95000 + 3700 + 60000
  assert.equal(totals.value.discount, 0);
  assert.equal(totals.value.vat, 20283); // 19950 + 333 + 0
  assert.equal(totals.value.total, 178983);
});

